<?php declare(strict_types=1);namespace App\Modules\SubcontractBoq\Repositories;use App\Core\Database\Database;use App\Modules\SubcontractBoq\DTOs\BoqItemData;use App\Modules\SubcontractBoq\DTOs\BoqSectionData;final class SubcontractBoqRepository{public function __construct(private readonly Database $db){}public function contract(int $id):?array{$r=$this->db->execute('SELECT id,subcontract_code contract_code,title,pricing_method,status,contract_value FROM subcontracts WHERE id=? LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}public function boq(int $contractId):?array{$r=$this->db->execute('SELECT * FROM subcontract_boqs WHERE subcontract_id=? LIMIT 1',[$contractId]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}public function create(int $contractId):int{$this->db->execute("INSERT INTO subcontract_boqs(subcontract_id,status) VALUES(?,'draft')",[$contractId]);return(int)$this->db->connection()->insert_id;}public function sections(int $boqId):array{$r=$this->db->execute('SELECT s.*,COALESCE(SUM(i.line_total),0) subtotal FROM subcontract_boq_sections s LEFT JOIN subcontract_boq_items i ON i.subcontract_boq_section_id=s.id WHERE s.subcontract_boq_id=? GROUP BY s.id ORDER BY s.sort_order,s.id',[$boqId]);$rows=$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[];foreach($rows as &$s){$s['items']=$this->items((int)$s['id']);}return$rows;}public function items(int $sectionId):array{$r=$this->db->execute('SELECT * FROM subcontract_boq_items WHERE subcontract_boq_section_id=? ORDER BY sort_order,id',[$sectionId]);return$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[];}public function section(int $id):?array{$r=$this->db->execute('SELECT s.*,b.subcontract_id,b.status boq_status FROM subcontract_boq_sections s JOIN subcontract_boqs b ON b.id=s.subcontract_boq_id WHERE s.id=? LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}public function item(int $id):?array{$r=$this->db->execute('SELECT i.*,s.subcontract_boq_id,b.subcontract_id,b.status boq_status FROM subcontract_boq_items i JOIN subcontract_boq_sections s ON s.id=i.subcontract_boq_section_id JOIN subcontract_boqs b ON b.id=s.subcontract_boq_id WHERE i.id=? LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}public function activeWorkSection(int $id):?array{$r=$this->db->execute('SELECT id,section_code,name FROM work_sections WHERE id=? AND is_active=1 LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}public function activeCostCode(int $id):?array{$r=$this->db->execute('SELECT c.id,c.cost_code,c.name,c.default_unit_id FROM cost_codes c JOIN work_sections s ON s.id=c.work_section_id WHERE c.id=? AND c.is_active=1 AND s.is_active=1 LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}public function activeUnit(int $id):?array{$r=$this->db->execute('SELECT id,name_ar,symbol_ar FROM units WHERE id=? AND is_active=1 LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}public function masters():array{foreach(['sections'=>'SELECT id,section_code,name FROM work_sections WHERE is_active=1 ORDER BY sort_order','codes'=>'SELECT c.id,c.cost_code,c.name,c.default_unit_id FROM cost_codes c JOIN work_sections s ON s.id=c.work_section_id WHERE c.is_active=1 AND s.is_active=1 ORDER BY c.cost_code','units'=>'SELECT id,name_ar,symbol_ar FROM units WHERE is_active=1 ORDER BY sort_order'] as $k=>$sql){$r=$this->db->execute($sql);$data[$k]=$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[];}return$data;}public function addSection(int $boqId,BoqSectionData $d):int{$this->db->execute('INSERT INTO subcontract_boq_sections(subcontract_boq_id,work_section_id,section_code,title,description,sort_order) VALUES(?,?,?,?,?,?)',[$boqId,$d->workSectionId,$d->sectionCode,$d->title,$d->description,$d->sortOrder]);return(int)$this->db->connection()->insert_id;}public function updateSection(int$id,BoqSectionData$d):void{$this->db->execute('UPDATE subcontract_boq_sections SET work_section_id=?,section_code=?,title=?,description=?,sort_order=? WHERE id=?',[$d->workSectionId,$d->sectionCode,$d->title,$d->description,$d->sortOrder,$id]);}public function addItem(BoqItemData$d,?array$u):int{$this->db->execute('INSERT INTO subcontract_boq_items(subcontract_boq_section_id,cost_code_id,item_code,description,unit_id,unit_name,unit_symbol,quantity,unit_rate,sort_order,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$d->sectionId,$d->costCodeId,$d->itemCode,$d->description,$d->unitId,$u['name_ar']??null,$u['symbol_ar']??null,$d->quantity,$d->unitRate,$d->sortOrder,$d->notes]);return(int)$this->db->connection()->insert_id;}public function updateItem(int$id,BoqItemData$d,?array$u):void{$this->db->execute('UPDATE subcontract_boq_items SET cost_code_id=?,item_code=?,description=?,unit_id=?,unit_name=?,unit_symbol=?,quantity=?,unit_rate=?,sort_order=?,notes=? WHERE id=?',[$d->costCodeId,$d->itemCode,$d->description,$d->unitId,$u['name_ar']??null,$u['symbol_ar']??null,$d->quantity,$d->unitRate,$d->sortOrder,$d->notes,$id]);}public function removeItem(int$id):void{$this->db->execute('DELETE FROM subcontract_boq_items WHERE id=?',[$id]);}public function removeSection(int$id):void{$this->db->execute('DELETE FROM subcontract_boq_sections WHERE id=?',[$id]);}public function removeItems(int$section):void{$this->db->execute('DELETE FROM subcontract_boq_items WHERE subcontract_boq_section_id=?',[$section]);}public function discard(int$boq):void{$this->db->execute('DELETE FROM subcontract_boqs WHERE id=?',[$boq]);}public function countItems(int$boq):int{$r=$this->db->execute('SELECT COUNT(*) n FROM subcontract_boq_items i JOIN subcontract_boq_sections s ON s.id=i.subcontract_boq_section_id WHERE s.subcontract_boq_id=?',[$boq]);return(int)(($r instanceof \mysqli_result?$r->fetch_assoc():[])['n']??0);}public function incompleteItems(int$boq):int{$r=$this->db->execute('SELECT COUNT(*) n FROM subcontract_boq_items i JOIN subcontract_boq_sections s ON s.id=i.subcontract_boq_section_id WHERE s.subcontract_boq_id=? AND (i.unit_id IS NULL OR i.quantity IS NULL OR i.unit_rate IS NULL)',[$boq]);return(int)(($r instanceof \mysqli_result?$r->fetch_assoc():[])['n']??0);}public function total(int$boq):string{$r=$this->db->execute('SELECT COALESCE(SUM(i.line_total),0) total FROM subcontract_boq_items i JOIN subcontract_boq_sections s ON s.id=i.subcontract_boq_section_id WHERE s.subcontract_boq_id=?',[$boq]);return(string)(($r instanceof \mysqli_result?$r->fetch_assoc():[])['total']??'0.00');}public function approve(int$boq,int$user,string$total,bool$sync):void{$this->db->execute("UPDATE subcontract_boqs SET status='approved',approved_at=NOW(),approved_by=? WHERE id=? AND status='draft'",[$user,$boq]);if($sync)$this->db->execute('UPDATE subcontracts c JOIN subcontract_boqs b ON b.subcontract_id=c.id SET c.contract_value=? WHERE b.id=?',[$total,$boq]);}}
